const checksum = (ring) => ring.reduce((s, [x, y]) => s + x * 7 + y * 13, 0);

/** Apply `indiaShapeFixes` (runs after the Nepal fixes; throws if a target is missing or changed). */
export function applyIndiaShapeFixes(entities) {
  const byId = (id) => {
    const ent = entities.find((x) => x.id === id);
    if (!ent) throw new Error(`india fixes: no entity ${id}`);
    return ent;
  };
  for (const [id, years] of Object.entries(IN_HOLDS)) {
    const ent = byId(id);
    for (const [y, from] of Object.entries(years)) {
      const src = ent.overlays.find((o) => o.year === from);
      if (!src || ent.overlays.some((o) => o.year === Number(y))) throw new Error(`india fixes: ${id} cannot hold ${from} to ${y}`);
      ent.overlays.push({ ...src, year: Number(y), regions: src.regions.map((r) => (typeof r === 'string' ? r : { ...r, ring: r.ring && r.ring.map((p) => [...p]) })) });
    }
    ent.overlays.sort((a, b) => a.year - b.year);
  }
  const { _bake: bake = {}, ...trims } = IN_TRIMS;
  for (const [id, regions] of Object.entries(trims)) {
    const ent = byId(id);
    for (const [region, rings] of Object.entries(regions)) {
      for (const [y, { sum, ring }] of Object.entries(rings)) {
        const kf = ent.overlays.find((o) => o.year === Number(y));
        const r = kf?.regions.find((q) => typeof q !== 'string' && q.id === region);
        if (!r?.ring || Math.abs(checksum(r.ring) - sum) > 1e-6) throw new Error(`india fixes: ${id} ${region} ${y} changed — regenerate the trim`);
        if (ring) r.ring = ensureClockwise(ring);
        else kf.regions = kf.regions.filter((q) => q !== r); // nothing left once trimmed
      }
    }
  }
  // Baked in-between keyframes (trimmed copies of the drawn morph, every region of the entity), so the
  // morph cannot cut back over the pack between two trimmed keyframes.
  for (const [id, years] of Object.entries(bake)) {
    const ent = byId(id);
    for (const [y, regions] of Object.entries(years)) {
      const year = Number(y);
      const prev = [...ent.overlays].reverse().find((o) => o.year < year);
      const next = ent.overlays.find((o) => o.year > year);
      if (!prev || !next || ent.overlays.some((o) => o.year === year)) throw new Error(`india fixes: ${id} ${y} cannot be baked`);
      const named = (rid) => [...prev.regions, ...next.regions].find((r) => typeof r !== 'string' && r.id === rid)?.name || rid;
      ent.overlays.push({ ...prev, year, regions: Object.entries(regions).map(([rid, ring]) => ({ id: rid, name: named(rid), ring: ensureClockwise(ring) })) });
    }
    ent.overlays.sort((a, b) => a.year - b.year);
  }
}

